"use client";
import {
  ReusableTable,
  indexColumn,
  statusColumn,
  actionsColumn,
  Column,
} from "@/components/tables";
import { User } from "@/lib/auth";
import { PERMISSIONS } from "@/lib/permissions";

type Props = {
  owners: User[];
  loading?: boolean;
  onDetail: (owner: User) => void;
  onEdit?: (owner: User) => void;
  onDelete?: (owner: User) => void;
  onResetPassword?: (owner: User) => void;
};

export function UserTable({
  owners,
  loading,
  onDetail,
  onEdit,
  onDelete,
  onResetPassword,
}: Props) {
  const columns: Column<User>[] = [
    indexColumn<User>(),
    {
      key: "userCode",
      header: "User ID",
      render: (row) => <span className="font-mono font-bold text-primary">{row.userCode || "—"}</span>,
    },
    {
      key: "fullName",
      header: "Name",
      render: (row) => row.fullName,
    },
    { key: "email", header: "Email" },
    { key: "phoneNumber", header: "Phone" },
    {
      key: "role",
      header: "Role",
      render: (row) => (
        <span className="uppercase text-xs font-bold">
          {row.role?.replace(/_/g, " ")}
        </span>
      ),
    },
    statusColumn<User>(),
    actionsColumn<User>({
      onDetail,
      detailPermission: PERMISSIONS.USER_VIEW,
      onEdit,
      editPermission: PERMISSIONS.USER_UPDATE,
      onDelete,
      deletePermission: PERMISSIONS.USER_DELETE,
      onResetPassword,
      resetPasswordPermission: PERMISSIONS.SETTINGS_RESET_PASSWORD,
    }),
  ];

  return (
    <ReusableTable
      data={owners}
      columns={columns}
      getRowKey={(row) => row.id}
      emptyText={loading ? "Loading owners..." : "No parking owners found"}
    />
  );
}
